WITH base AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, ROUND(DATEDIFF(ends_on, starts_on) / 30, 1) months_starts_on_to_ends_on FROM promotions WHERE starts_on >= DATE '2023-08-03') SELECT id, promo_code, metric_name, metric_value FROM (SELECT id, promo_code, months_starts_on_to_ends_on, discount_pct FROM base) src UNPIVOT (metric_value FOR metric_name IN (months_starts_on_to_ends_on, discount_pct AS DISCOUNT_PCT_VAL));
